    image_patch = ImagePatch(image)
    hood_patches = image_patch.find("hood")
    truck_patches = image_patch.find("truck")

    if not hood_patches or not truck_patches:
        return image_patch

    min_distance = float('inf')
    closest_hood = None

    for hood in hood_patches:
        for truck in truck_patches:
            if hood.overlaps_with(truck.left, truck.lower, truck.right, truck.upper):
                continue
            dist = abs(hood.horizontal_center - truck.horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_hood = hood

    return closest_hood

