def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    tennis_ball_patches = image_patch.find("tennis ball")

    if not tennis_ball_patches:
        return image_patch

    # Remove the tennis ball touching the line
    line_patches = image_patch.find("line")
    if line_patches:
        touching_line = [tb for tb in tennis_ball_patches if tb.overlaps_with(line_patches[0].left, line_patches[0].lower, line_patches[0].right, line_patches[0].upper)]
        if touching_line:
            tennis_ball_patches.remove(touching_line[0])

    # Remove the tennis ball on the far right
    tennis_ball_patches.sort(key=lambda p: p.right)
    if len(tennis_ball_patches) > 1:
        tennis_ball_patches.pop()

    return tennis_ball_patches[0] if tennis_ball_patches else image_patch

